import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Recommendation Engine hoạt động ra sao","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/index.md","filePath":"decisions/index.md"}'),o={name:"decisions/index.md"};function c(g,n,r,e,u,s){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="recommendation-engine-hoat-đong-ra-sao" tabindex="-1">Recommendation Engine hoạt động ra sao <a class="header-anchor" href="#recommendation-engine-hoat-đong-ra-sao" aria-label="Permalink to &quot;Recommendation Engine hoạt động ra sao&quot;">​</a></h1><p>Trên trang này# Recommendation Engine hoạt động ra sao <a href="#recommendation-engine-hoat-đong-ra-sao">​</a> Mỗi khi learner mở Nemo12, hệ thống phải trả lời một câu: <strong>việc gì là việc đáng làm nhất ngay bây giờ?</strong> Trang này giải thích cách nó tính, và vì sao câu trả lời đôi khi rất khác trực giác.</p><h2 id="tam-lua-chon-khong-phai-mot-​" tabindex="-1">Tám lựa chọn, không phải một <a href="#tam-lua-chon-khong-phai-mot">​</a> <a class="header-anchor" href="#tam-lua-chon-khong-phai-mot-​" aria-label="Permalink to &quot;Tám lựa chọn, không phải một [​](#tam-lua-chon-khong-phai-mot)&quot;">​</a></h2><p>Hệ thống không chỉ chọn &quot;học bài nào&quot;. Nó cân nhắc tám loại hành động: Hành độngKhi nào<strong>Học phần X</strong>Có lỗ hổng rõ, đã sẵn sàng để học<strong>Ôn phần Y</strong>Từng vững, đang mờ dần<strong>Đo phần Z</strong>Chưa đủ dữ liệu để quyết định gì<strong>Bỏ qua</strong>Đã đủ vững, đi tiếp là hợp lý<strong>Luyện tập</strong>Hiểu rồi, cần thành thục<strong>Hỏi mentor</strong>Đã kẹt nhiều lần, cần người thật<strong>Nghỉ</strong>Đang quá tải hoặc lợi ích thêm quá thấp<strong>Ôn thi</strong>Sắp thi, chuyển sang chế độ khácViệc &quot;nghỉ&quot; nằm trong danh sách là có chủ đích. Một hệ thống chỉ biết đề xuất học thêm sẽ luôn đề xuất học thêm, kể cả khi đó là điều tệ nhất có thể làm lúc đó.</p><h2 id="cong-thuc-​" tabindex="-1">Công thức <a href="#cong-thuc">​</a> <a class="header-anchor" href="#cong-thuc-​" aria-label="Permalink to &quot;Công thức [​](#cong-thuc)&quot;">​</a></h2><p>textMức ưu tiên = Tác động kỳ vọng — làm việc này thì cải thiện được bao nhiêu × Liên quan tới mục tiêu — có phục vụ điều learner đang hướng tới không × Mức khẩn — còn bao nhiêu thời gian × Tầm quan trọng nền — phần này chặn bao nhiêu thứ phía sau × Xác suất thành công — learner làm được không, hay sẽ nản ÷ Chi phí — thời gian, sức, tải nhận thức (+ Nhu cầu thông tin, khi hệ thống chưa biết đủ)Sáu yếu tố, nhân và chia với nhau. Điểm quan trọng: <strong>không yếu tố nào một mình quyết định được</strong>. Một phần kiến thức rất yếu nhưng không liên quan mục tiêu nào và cũng không chặn gì phía sau sẽ có ưu tiên thấp. Một phần chỉ hơi yếu nhưng đang chặn hàng chục bài khác sẽ lên đầu.</p><h2 id="vi-du-that-​" tabindex="-1">Ví dụ thật <a href="#vi-du-that">​</a> <a class="header-anchor" href="#vi-du-that-​" aria-label="Permalink to &quot;Ví dụ thật [​](#vi-du-that)&quot;">​</a></h2><p>Learner lớp 8, hai lựa chọn: Phân số (lớp 5)Chương mới trên lớpMức vững hiện tại0.550.30Chặn bao nhiêu phần khác342Liên quan mục tiêucao (nền cho mọi thứ)trung bìnhXác suất thành côngcaothấp — thiếu nền<strong>Ưu tiên tính ra<strong><strong>0.91</strong></strong>0.43</strong>Hệ thống đề xuất <strong>phân số</strong>, dù đó là kiến thức lớp 5 và learner đang học lớp 8. Với nhiều gia đình, đề xuất này trông sai — con đang phải theo bài trên lớp cơ mà. Nhưng chương mới có xác suất thành công thấp <em>chính vì</em> phân số chưa vững. Học nó trước là cách nhanh nhất để chương mới trở nên khả thi. Đây cũng là lý do nhiều buổi học thêm không tạo ra kết quả: chúng dạy đúng nội dung trên lớp, trong khi mắt xích đứt nằm ở chỗ khác.</p><h2 id="moi-goi-y-đeu-luu-ly-do-​" tabindex="-1">Mọi gợi ý đều lưu lý do <a href="#moi-goi-y-đeu-luu-ly-do">​</a> <a class="header-anchor" href="#moi-goi-y-đeu-luu-ly-do-​" aria-label="Permalink to &quot;Mọi gợi ý đều lưu lý do [​](#moi-goi-y-đeu-luu-ly-do)&quot;">​</a></h2><p>Mỗi recommendation được lưu kèm: lý do, phiên bản dữ liệu về learner tại thời điểm đó, phiên bản mục tiêu, phiên bản hoàn cảnh, và phiên bản thuật toán. Nghĩa là hệ thống luôn trả lời được: <em>&quot;Hôm nay khác hôm qua vì: có thêm lịch thi học kỳ, có ghi nhận con ốm, thời gian rảnh tuần này giảm 60 phút, và mức sẵn sàng phần Hình học vừa được tính lại.&quot;</em> Một hệ thống không giải thích được lời khuyên của mình là hệ thống bạn không có cách nào kiểm tra. Với những quyết định ảnh hưởng tới nhiều năm của một đứa trẻ, đó là điều không chấp nhận được.</p><h2 id="nam-trang-tiep-theo-​" tabindex="-1">Năm trang tiếp theo <a href="#nam-trang-tiep-theo">​</a> <a class="header-anchor" href="#nam-trang-tiep-theo-​" aria-label="Permalink to &quot;Năm trang tiếp theo [​](#nam-trang-tiep-theo)&quot;">​</a></h2><p><a href="/decisions/hoc-test-nghi">**Vì sao lúc &quot;học&quot;, lúc &quot;test&quot;, lúc &quot;nghỉ&quot;**Ba loại đề xuất trông rất khác nhau, nhưng đến từ cùng một phép tính.</a><a href="/decisions/cach-day"><strong>Một node, nhiều cách dạy</strong>Hệ thống không chỉ chọn học phần nào, mà còn chọn phần đó nên được dạy theo cách nào.</a><a href="/decisions/khac-goi-y"><strong>Vì sao hai bạn cùng tuổi nhận gợi ý khác nhau</strong>Tuổi và lớp gần như không xuất hiện trong công thức. Đây là lý do.</a><a href="/decisions/readiness-vs-mastery"><strong>Readiness khác Mastery thế nào</strong>&quot;Toán khá&quot; nhưng &quot;chưa sẵn sàng thi chuyên&quot; — hai câu không hề mâu thuẫn.</a><a href="/decisions/retention"><strong>Quên và ôn tập ảnh hưởng gợi ý ra sao</strong>Từng vững và hiện còn nhớ là hai con số riêng biệt. Đây là chỗ nhiều thời gian được tiết kiệm.</a>Câu hỏi của Recommendation Engine không phải &quot;learner còn thiếu gì&quot; — luôn thiếu rất nhiều. Mà là: &quot;trong tất cả những thứ có thể làm giờ này, cái nào đáng nhất?&quot;</p>',12)])])}const p=h(o,[["render",c]]);export{m as __pageData,p as default};
